import React, { useState, useEffect } from "react";
import useSound from "use-sound";
import clockcalarm from "./clock-alarm.mp3";

const Alarm = () => {
  const [time, setTime] = useState("");
  const [alarmTime, setAlarmTime] = useState(null);
  const [alarmName, setAlarmName] = useState("");
  const [message, setMessage] = useState("");
  const [play, { stop }] = useSound(clockcalarm);

  useEffect(() => {
    const interval = setInterval(() => {
      const now = new Date();
      const currentTime = now.toTimeString().slice(0, 5);

      if (alarmTime === currentTime) {
        play(); // Start the alarm sound
        setTimeout(() => {
          alert(`${alarmName || "Alarm"} it's ${currentTime}`);
          stop(); // Stop sound after alert is closed
        }, 100);

        setAlarmTime(null); // Reset alarm time
        setAlarmName(""); // Clear alarm name
        setMessage(""); // Clear the message
      }
    }, 1000);

    return () => clearInterval(interval);
  }, [alarmTime, alarmName, play, stop]);

  const setAlarm = () => {
    if (time) {
      setAlarmTime(time);
      setMessage(`Alarm "${alarmName || "Unnamed Alarm"}" is set for ${time}`);
    }
  };

  const cancelAlarm = () => {
    setAlarmTime(null);
    setAlarmName("");
    setMessage("Alarm has been canceled.");
    setTimeout(() => setMessage(""), 2000); // Clear the message after 2 seconds
  };

  return (
    <div className="min-w-80">
      <h1 className="text-2xl text-white text-center font-serif mb-4">
        Set Alarm
      </h1>
      <div className="flex flex-col space-y-3">
        <input
          type="text"
          placeholder="Alarm Name"
          value={alarmName}
          onChange={(e) => setAlarmName(e.target.value)}
          className="text-xm  md:text-xl p-2 rounded-md  bg-white text-black font-dotgothic"
        />
        <input
          type="time"
          value={time}
          onChange={(e) => setTime(e.target.value)}
          className="text-xm  md:text-xl p-2 rounded-md bg-white text-black font-dotgothic"
        />
        <div className="flex justify-between">
          <button
            onClick={cancelAlarm}
            className="bg-red-500 hover:bg-red-600 rounded-lg text-xm font-serif text-white px-4 py-3"
          >
            Cancel
          </button>
          <button
            onClick={setAlarm}
            className="bg-green-500 hover:bg-green-600 rounded-lg text-xm font-serif text-white px-4 py-3"
          >
            Done
          </button>
        </div>
      </div>
      {message && (
        <p className="text-red-500 font-semibold text-center underline text-xm mt-4">
          {message}
        </p>
      )}
    </div>
  );
};

export default Alarm;
